export default {"id":"production-level-13","number":13,"title":"Module 13 — Remix and Flip","skillBand":"Textbook","duration":"From the course textbook","summary":"1. A Remix must preserve the Key Identifiable Element (usually the lead vocal topline) so an independent listener immediately recognizes the original song. 2. Suite AI Stem Separation is NOT an owned tool. Remix workflows utilize official s","modules":[{"id":"production-m-13-1","code":"13","title":"Section C: Remix and Flip Craft (Part A: The Remix)","blurb":"1. A Remix must preserve the Key Identifiable Element (usually the lead vocal topline) so an independent listener immediately recognizes the original song. 2. Suite AI Stem Separation is NOT an owned tool. Remix workflows utilize official s","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"production-l-o-17","title":"Section overview","blocks":[{"type":"step","title":"overview","blocks":[{"type":"heading","text":"Module 13 — Section C: Remix and Flip Craft (Part A: The Remix)","level":1},{"type":"prose","html":"<strong>Intent:</strong> Master the transformational art and legal framework of the official commercial Remix. Ingest and warp multi-track foreign stems, execute off-grid vocal transient correction, implement the 6 canonical EDMProd remix architectures, enforce the key identifiable element anchor, and produce 100% original drums, bass, and harmony in Ableton Live 12 Standard.   <strong>Required Core Module.</strong>   <strong>Strict Pedagogical Invariants:</strong>  "},{"type":"list","items":["A Remix must preserve the <strong>Key Identifiable Element</strong> (usually the lead vocal topline) so an independent listener immediately recognizes the original song.","Suite AI Stem Separation is NOT an owned tool. Remix workflows utilize official stem packs, royalty-free vocal kits, or parametric breakdown filtering.","Every external audio source must be logged in writing with verified legal provenance.  "],"ordered":true},{"type":"prose","html":"<strong>Primary Source References:</strong> EDMProd (<em>How to Remix a Song: The 6 Approaches &amp; 15 Practical Tips</em> / Sam Matla); <em>The Ultimate Remix Guide.pdf</em>; <em>Ableton EDM Remixing Guide.pdf</em>; <em>Drum Breaks_ A Guide To Injecting Character into Your Music.pdf</em>; Ableton Live 12 Reference Manual (Ch. 9: Warping, Ch. 11: Audio to MIDI); <em>Music-Production-Songwriting-Knowledgebase.md</em> (§1.1, §1.2, §14, §15)."},{"type":"heading","text":"Section 13.1 — Definitions, Derivative Rights, and Legal Ingestion","level":1},{"type":"prose","html":"<strong>Section ID:</strong> <code>production-m13-1</code>   <strong>Learning Outcomes:</strong>"},{"type":"list","items":["Distinguish the precise legal and artistic definitions of Remix, Flip, Cover, Bootleg, and Mashup.","Understand the dual-copyright structure (Musical Composition © vs. Master Sound Recording ℗) and derivative work law.","Establish why unauthorized commercial sampling has zero fair use protection.","Select candidate songs that actively benefit from a transformational remix.","Formulate the pre-production game plan and maintain the written source log."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-1","title":"13.1.1 — The Transformational Taxonomy: Remix vs. Flip vs. Cover vs. Bootleg vs. Mashup","blocks":[{"type":"step","title":"13.1.1 — The Transformational Taxonomy: Remix vs. Flip vs. Cover vs. Bootleg vs. Mashup","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Define the five categories of derivative music production.  "}]},{"type":"step","title":"1. The Five Derivative Typologies","blocks":[{"type":"prose","html":"In professional music production, precision of terminology is essential:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">graph TD\n    Source[\"Original Commercial Song\"]\n    Source --&gt;|Retains Key Element / New Production| Remix[\"1. REMIX&lt;br&gt;A transformational re-production built around a recognizable core stem.\"]\n    Source --&gt;|Granular Slicing / Deconstructs Identity| Flip[\"2. FLIP&lt;br&gt;Source audio treated as raw quarry; identity becomes new material.\"]\n    Source --&gt;|Re-records Composition from Scratch| Cover[\"3. COVER&lt;br&gt;100% newly recorded audio reproducing the underlying composition.\"]\n    Source --&gt;|Unauthorized Remix of Master Audio| Bootleg[\"4. BOOTLEG&lt;br&gt;An unofficial remix utilizing commercial audio without clearance.\"]\n    Source --&gt;|Superimposes Stems from Multiple Songs| Mashup[\"5. MASHUP&lt;br&gt;Acapella of Song A over Instrumental of Song B.\"]</pre>"},{"type":"list","items":["<strong>The Remix Invariant</strong>: A remix balances familiarity with transformation. If a listener cannot identify the original song within 5 seconds of the vocal entry, you did not produce a remix—you produced an original track that happens to share a folder with foreign stems."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-2","title":"13.1.2 — Dual-Copyright Architecture: Composition (©) vs. Master (℗)","blocks":[{"type":"step","title":"13.1.2 — Dual-Copyright Architecture: Composition (©) vs. Master (℗)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Master the legal mechanics of music licensing and derivative works.  "}]},{"type":"step","title":"1. The Two Halves of Music Copyright","blocks":[{"type":"prose","html":"Every commercial recorded song consists of two entirely distinct legal properties:"},{"type":"table","headers":["Property","Symbol","Definition","Owner / Rights Holder","Required Clearance for Remix"],"rows":[["<strong>Musical Work (Composition)</strong>","<strong>©</strong>","The underlying melody, chord progression, and lyrics written by the songwriter.","Songwriters / Music Publishers (ASCAP, BMI, PRS).","Mechanical / Sync / Derivative Work License."],["<strong>Sound Recording (Master)</strong>","<strong>℗</strong>","The physical audio recording of acoustic sound waves fixed in a medium.","Record Label / Performing Artists.","Master Use License (Clearance to touch the audio files)."]],"caption":null},{"type":"list","items":["Under copyright law (17 U.S.C. § 106), the copyright owner possesses the exclusive right to prepare <strong>Derivative Works</strong>. Producing a remix without explicit authorization from both © and ℗ holders creates an unauthorized derivative work."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-3","title":"13.1.3 — Consent and Fair Use: Why \"Everyone Does It\" Is NOT Legal Advice","blocks":[{"type":"step","title":"13.1.3 — Consent and Fair Use: Why \"Everyone Does It\" Is NOT Legal Advice","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Demolish the myths surrounding sampling clearance and fair use.  "}]},{"type":"step","title":"1. The Legal Reality of Fair Use","blocks":[{"type":"prose","html":"Under landmark copyright rulings (<em>Bridgeport Music v. Dimension Films</em>, <em>Grand Upright Music v. Warner Bros</em>):"},{"type":"list","items":["<strong>Physical Sampling Invariant</strong>: Even sampling a 1-second guitar chord or snare hit from a commercial recording constitutes physical infringement of the master copyright (℗) without a de minimis defense.","<strong>Fair Use Immunity</strong>: Strictly limited to parody, academic criticism, news reporting, and non-commercial educational study. Releasing a bootleg on Spotify, Apple Music, Beatport, or YouTube (even with zero monetization) is commercial distribution subject to immediate takedowns, channel strikes, and statutory damages."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-4","title":"13.1.4 — Why Suite Stem Separation Is NOT a Student Step","blocks":[{"type":"step","title":"13.1.4 — Why Suite Stem Separation Is NOT a Student Step","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Master parametric breakdown extraction without relying on AI stem splitters.  "}]},{"type":"step","title":"1. The Live 12 Standard Reality","blocks":[{"type":"prose","html":"Ableton Live 12 Standard does not include proprietary AI Stem Separation. In professional practice, AI stem splitters introduce severe phase artifacts, watery flanging, and pre-ringing transients into vocal acapellas."},{"type":"list","items":["Student producers in this course rely on:","Official lossless multi-track stems provided in authorized remix contests.","Royalty-free acapella kits from commercial sound libraries.","Clean breakdown slicing from stereo mixes where drums are naturally absent."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-5","title":"13.1.5 — Selecting a Candidate That Actively Benefits from a Remix (EDMProd #1)","blocks":[{"type":"step","title":"13.1.5 — Selecting a Candidate That Actively Benefits from a Remix (EDMProd #1)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Identify songs with acoustic headroom and transformational potential.  "}]},{"type":"step","title":"1. Selection Criteria (Sam Matla)","blocks":[{"type":"prose","html":"Never remix a modern, densely packed electronic festival banger—it already has 100 tracks filling every frequency bin."},{"type":"list","items":["<strong>Ideal Candidates</strong>:","<strong>Acoustic / Folk Ballads</strong>: A beautiful acoustic vocal at 75 BPM that can be accelerated to 124 BPM house.","<strong>Vintage Soul / R&amp;B</strong>: An expressive, emotional vocal with sparse instrumentation.","<strong>Indie Rock Tracks</strong>: Memorable vocal toplines trapped in muddy, narrow lo-fi arrangements."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-6","title":"13.1.6 — Auditing Gaps and Formulating the Game Plan (EDMProd #2–3)","blocks":[{"type":"step","title":"13.1.6 — Auditing Gaps and Formulating the Game Plan (EDMProd #2–3)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Document the creative production roadmap before opening Ableton Live.  "}]},{"type":"step","title":"1. Pre-Production Game Plan Formulation","blocks":[{"type":"prose","html":"Write down the answers to these three questions in <code>REMIX_GAMEPLAN.txt</code>:"},{"type":"list","items":["<strong>The Invariant</strong>: What is the single emotional element I MUST keep? <em>(e.g., The lead chorus vocal acapella)</em>.","<strong>The Deletions</strong>: What original elements will I discard immediately? <em>(e.g., All original 808s, synths, and guitars)</em>.","<strong>The Additions</strong>: What brand-new production will I introduce? <em>(e.g., A heavy 4-on-the-floor kick, rolling sub-bass, and bright piano stabs)</em>."],"ordered":true}]}],"minutes":8},{"id":"production-l13-1-7","title":"13.1.7 — Target Audience Context: Club vs. Radio vs. Re-Harmonization","blocks":[{"type":"step","title":"13.1.7 — Target Audience Context: Club vs. Radio vs. Re-Harmonization","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Align arrangement duration and energy to the intended listening environment.  "}]},{"type":"step","title":"1. Three Commercial Output Targets","blocks":[{"type":"list","items":["<strong>The Extended Club Remix (124–128 BPM)</strong>: Built for DJ sets. Features a 32-bar unmelodic intro with heavy kick and open hats, leading to an energetic build and massive club drop.","<strong>The Radio / Streaming Remix (2.5–3.0 min)</strong>: Built for Spotify playlists. The vocal hook arrives within 20 seconds, with an explosive drop before 0:45.","<strong>The Harmonic Re-Interpretation</strong>: Built for musical showcase. Transposes minor-key vocals over lush major-9th jazz-pop harmonies."],"ordered":false}]}],"minutes":8},{"id":"production-l13-1-8","title":"13.1.8 — Stereo Mix Extraction: Slicing the Breakdown (EDMProd #4)","blocks":[{"type":"step","title":"13.1.8 — Stereo Mix Extraction: Slicing the Breakdown (EDMProd #4)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Extract clean vocal chops from a stereo mix when multi-track stems are unavailable.  "}]},{"type":"step","title":"1. The Breakdown Extraction Technique","blocks":[{"type":"prose","html":"If you do not possess multi-track stems:"},{"type":"list","items":["Audition the stereo track to find the <strong>Mid-Song Breakdown</strong> (where drums and bass drop out, leaving only the vocal over a soft pad).","Slice out the 4-bar or 8-bar vocal phrase (<code>Ctrl + E</code>).","Insert Live's stock <strong>EQ Eight</strong>. Engage a 48 dB/oct high-pass filter at 180 Hz to eliminate any low-end rumble.","Insert <strong>Utility</strong> and engage the <code>Bass Mono</code> switch below 120 Hz."],"ordered":true}]}],"minutes":8},{"id":"production-l13-1-9","title":"13.1.9 — The Formal Source Provenance Log","blocks":[{"type":"step","title":"13.1.9 — The Formal Source Provenance Log","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Document licensing origin and stem provenance in the project folder.  "}]},{"type":"step","title":"1. Source Log Requirements","blocks":[{"type":"prose","html":"Create <code>SOURCE_LOG.txt</code> in your project folder:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">===================================================================\nDELIVERABLE 3: REMIX SOURCE PROVENANCE LOG\n===================================================================\n- Song Title: \"Acoustic Horizon\"\n- Original Artist: Jane Doe\n- Origin / Platform: Official Splice Stem Contest / Cleared Royalty-Free Kit\n- Licensing Status: Authorized for Educational Remix Production\n- Stems Ingested: Lead_Vocal_Dry.wav (24-bit / 44.1 kHz), Vocal_Adlibs.wav\n- Original Key: C Major | Original BPM: 78.0 BPM\n===================================================================</pre>"}]}],"minutes":8},{"id":"production-l13-1-10","title":"13.1.10 — Course Ethics: What This School Will Not Help You Upload","blocks":[{"type":"step","title":"13.1.10 — Course Ethics: What This School Will Not Help You Upload","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Distinguish academic educational practice from commercial distribution liability.  "}]},{"type":"step","title":"1. Ethical Guidelines","blocks":[{"type":"prose","html":"This course teaches the professional transformational craft of remixing. Completing Gate F certifies your technical competency inside Ableton Live. It does NOT grant commercial distribution clearance for uncleared third-party master recordings."}]}],"minutes":8},{"id":"production-l13-2-1","title":"13.2.1 — Finding Source BPM and the 1.1.1 Downbeat Anchor","blocks":[{"type":"step","title":"13.2.1 — Finding Source BPM and the 1.1.1 Downbeat Anchor","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Lock foreign audio files to Ableton Live's global tempo grid.  "}]},{"type":"step","title":"1. Downbeat Locking Protocol","blocks":[{"type":"list","items":["Drag the source audio file onto Track 1 in Arrangement View.","Zoom into the very first transient peak where the kick drum or opening vocal phrase begins.","Right-click the exact transient marker  Select <strong>Set 1.1.1 Here</strong>.","Right-click the marker again  Select <strong>Warp From Here (Straight)</strong> or <strong>Warp at XXX BPM</strong>.","Set Live’s global tempo to match the calculated source tempo. Turn on the metronome (<code>C</code>) and verify that downbeats align with gridlines throughout the entire file."],"ordered":true}]}],"minutes":8},{"id":"production-l13-2-2","title":"13.2.2 — Warping Full Mixes with Complex / Complex Pro","blocks":[{"type":"step","title":"13.2.2 — Warping Full Mixes with Complex / Complex Pro","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Select the optimal psychoacoustic warp algorithm for polyphonic and vocal material.  "}]},{"type":"step","title":"1. Algorithm Selection Matrix","blocks":[{"type":"list","items":["<strong>Full Polyphonic Stereo Mixes</strong>: Set Warp Mode to <strong>Complex</strong>. Complex uses psychoacoustic time-domain smearing designed to preserve dense drums, bass, and vocals simultaneously.","<strong>Isolated Lead Vocal Acapellas</strong>: Set Warp Mode to <strong>Complex Pro</strong>. Set <strong>Formants</strong> to <strong>100%</strong> and <strong>Envelope</strong> to <strong>128</strong>. This preserves natural throat resonance, preventing vocalists from sounding like chipmunks when transposed or time-stretched."],"ordered":false}]}],"minutes":8},{"id":"production-l13-2-3","title":"13.2.3 — Off-Grid Vocals: Localized Transient Correction","blocks":[{"type":"step","title":"13.2.3 — Off-Grid Vocals: Localized Transient Correction","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Correct rubato vocal phrasing without distorting the global file timing.  "}]},{"type":"step","title":"1. Surgical Warp Marker Pinning","blocks":[{"type":"prose","html":"When a singer performs with loose, expressive timing (singing slightly late or early):"},{"type":"list","items":["Do NOT drag the main clip boundary—this stretches the entire song out of time.","<strong>The Three-Marker Anchor Technique</strong>:","Double-click to place an anchor Warp Marker at the start of the measure before the error (e.g., Bar 9.1.1).","Double-click to place an anchor Warp Marker at the end of the measure (e.g., Bar 10.1.1).","Double-click the transient peak of the late vocal word on Beat 3  Drag only that middle marker to the exact Beat 3 grid line.","<em>Result</em>: The late vocal word snaps into perfect pocket while the surrounding audio remains completely undisturbed."],"ordered":false}]}],"minutes":8},{"id":"production-l13-2-4","title":"13.2.4 — Multi-Stem Group Alignment: The Shared Bar 1 Rule","blocks":[{"type":"step","title":"13.2.4 — Multi-Stem Group Alignment: The Shared Bar 1 Rule","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Warp and align multiple multi-track stems simultaneously.  "}]},{"type":"step","title":"1. Batch Multi-Stem Ingestion","blocks":[{"type":"prose","html":"When ingesting an official 15-stem remix pack:"},{"type":"list","items":["Select all 15 WAV files in the Windows File Explorer  Drag them simultaneously into Arrangement View.","Hold <code>Ctrl</code> to place each stem onto its own dedicated audio track.","Highlight all 15 audio clips simultaneously.","In the Clip View at the bottom: Enable <strong>Warp</strong> and set Mode to <strong>Complex</strong>.","Snap all 15 clip start headers to Bar <code>1.1.1</code>.","Because the stems share identical sample lengths, warping the Lead Vocal automatically aligns all 14 background stems in sample-accurate phase lock."],"ordered":true}]}],"minutes":8},{"id":"production-l13-2-5","title":"13.2.5 — The Bootleg Path: Isolating Usable Breakdowns","blocks":[{"type":"step","title":"13.2.5 — The Bootleg Path: Isolating Usable Breakdowns","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Prepare clean acoustic audio fragments from stereo commercial tracks.  "}]},{"type":"step","title":"1. Filtering and De-Rumbling","blocks":[{"type":"prose","html":"If working with a stereo master track:"},{"type":"list","items":["Isolate the 8-bar breakdown where drums are silent.","Apply high-pass filtering at 160 Hz to eliminate residual kick bleed.","Insert a utility gate or draw volume fades to silence breaths between vocal phrases."],"ordered":false}]}],"minutes":8},{"id":"production-l13-2-6","title":"13.2.6 — Key Strategy: Stay, Transpose, or Re-Harmonize","blocks":[{"type":"step","title":"13.2.6 — Key Strategy: Stay, Transpose, or Re-Harmonize","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Choose the tonal relationship between the vocal stem and your new production.  "}]},{"type":"step","title":"1. Three Tonal Paths","blocks":[{"type":"list","items":["<strong>Path 1: Preserve Original Key</strong>: Keep the vocal at 0 st transposition. Build new chords in the original key.","<strong>Path 2: Pitch Transposition</strong>: Transpose the vocal clip by +2 st or -3 st in Clip View to shift the track into a brighter or darker register.","<strong>Path 3: Modal Re-Harmonization</strong>: If the original vocal was in C Major (I - V - vi - IV), re-harmonize it in the relative minor (A Minor: i - VI - III - VII) or Dorian mode without changing the vocal pitch."],"ordered":true}]}],"minutes":8},{"id":"production-l13-2-7","title":"13.2.7 — Track Hierarchy Template: vs.","blocks":[{"type":"step","title":"13.2.7 — Track Hierarchy Template: vs.","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Enforce clean visual separation between borrowed stems and original production.  "}]},{"type":"step","title":"1. The Color-Coded Two-Group Structure","blocks":[{"type":"prose","html":"Organize your Live Set into two distinct Track Groups:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">graph TD\n    subgraph Live Set Hierarchy\n        G1[\"GROUP 1 (RED): SRC_STEMS&lt;br&gt;• SRC_Lead_Vocal&lt;br&gt;• SRC_Backing_Vox&lt;br&gt;• SRC_Guitar_Lick\"]\n        G2[\"GROUP 2 (BLUE): NEW_PRODUCTION&lt;br&gt;• NEW_Drums (Drum Rack)&lt;br&gt;• NEW_Bass (Drift Synth)&lt;br&gt;• NEW_Chords (Electric)&lt;br&gt;• NEW_Lead (Drift Lead)\"]\n    end</pre>"}]}],"minutes":8},{"id":"production-l13-2-8","title":"13.2.8 — Marking Original Sections First (EDMProd #5: Arrange ASAP)","blocks":[{"type":"step","title":"13.2.8 — Marking Original Sections First (EDMProd #5: Arrange ASAP)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Scaffold the original arrangement structure before writing new parts.  "}]},{"type":"step","title":"1. The \"Arrange ASAP\" Rule (Sam Matla)","blocks":[{"type":"prose","html":"Beginner producers spend 4 hours tweaking a kick drum under a 4-bar vocal loop and get stuck in the loop trap."},{"type":"list","items":["<strong>The Professional Ingestion Rule</strong>: Immediately upon warping the vocal, place Locators along the entire timeline matching the original song's structure: <code>SRC_Intro</code>, <code>SRC_Verse_1</code>, <code>SRC_Chorus_1</code>, <code>SRC_Verse_2</code>, <code>SRC_Chorus_2</code>, <code>SRC_Outro</code>.","Having the full timeline mapped prevents getting trapped in an 8-bar loop."],"ordered":false}]}],"minutes":8},{"id":"production-l13-2-9","title":"13.2.9 — Audio-to-MIDI Sketching of the Original Hook (EDMProd #12)","blocks":[{"type":"step","title":"13.2.9 — Audio-to-MIDI Sketching of the Original Hook (EDMProd #12)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Extract the underlying melodic notes of the source vocal into a clean MIDI roll.  "}]},{"type":"step","title":"1. Extraction Workflow","blocks":[{"type":"list","items":["Right-click the <code>SRC_Lead_Vocal</code> audio clip in Arrangement View.","Select <strong>Convert Melody to New MIDI Track</strong> (or <em>Convert Harmony to New MIDI Track</em> for acoustic chords).","Live’s neural pitch-tracking engine generates a new MIDI track containing the detected note events.","Open the MIDI Clip Editor (<code>Shift + Tab</code>). Clean up false ghost notes and octave jumps.","You now possess the exact MIDI pitch blueprint of their hook, allowing you to easily write interlocking basslines and counter-harmonies."],"ordered":true}]}],"minutes":8},{"id":"production-l13-2-10","title":"13.2.10 — Maintaining the Persistent Game-Plan Note","blocks":[{"type":"step","title":"13.2.10 — Maintaining the Persistent Game-Plan Note","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Keep pre-production constraints visible in Live's Set Info box.  "}]},{"type":"step","title":"1. Project Discipline","blocks":[{"type":"prose","html":"Open <strong>View  Overview / File Info Box</strong> in Live. Keep your target approach, BPM, and preserved element notes permanently visible to prevent creative drift."}]}],"minutes":8},{"id":"production-l13-3-1","title":"13.3.1 — Approach 1: Rewrite Chords and Harmony Around a Kept Vocal","blocks":[{"type":"step","title":"13.3.1 — Approach 1: Rewrite Chords and Harmony Around a Kept Vocal","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Compose brand-new chord progressions underneath the unedited vocal melody.  "}]},{"type":"step","title":"1. Re-Harmonization Mechanics (Matla)","blocks":[{"type":"prose","html":"Retain the unedited lead vocal stem. Delete all original synth, piano, and guitar tracks."},{"type":"list","items":["Compose a completely new 4-bar chord progression underneath the vocal notes.","<em>Example</em>: If the original pop song used a predictable I - V - vi - IV progression (C - G - Am - F), replace it with an emotional vi - IV - I - V (Am - F - C - G) or a jazzy ii7 - V7 - Imaj7 - VI7 (Dm7 - G7 - Cmaj7 - A7). The vocal remains familiar, but the emotional universe is completely transformed."],"ordered":false}]}],"minutes":8},{"id":"production-l13-3-2","title":"13.3.2 — Approach 2: Change Genre (Cross-Genre Translation)","blocks":[{"type":"step","title":"13.3.2 — Approach 2: Change Genre (Cross-Genre Translation)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Translate a song from its native stylistic clock into an entirely different genre.  "}]},{"type":"step","title":"1. Genre Clock Translation Examples","blocks":[{"type":"list","items":["<strong>Pop Ballad (75 BPM)  Melodic House (124 BPM)</strong>: Warp vocal with Complex Pro, program a rolling 4-on-the-floor kick, 16th-note offbeat bass, and sidechained synth chords.","<strong>House (126 BPM)  Drum &amp; Bass (174 BPM)</strong>: Accelerate the tempo, replace 4-on-the-floor drums with an energetic two-step Amen breakbeat and Reese sub-bass.","<strong>Hip-Hop (90 BPM)  Dubstep (140 BPM)</strong>: Shift vocal into halftime pocket with explosive wobble bass drops on Beat 3."],"ordered":false}]}],"minutes":8},{"id":"production-l13-3-3","title":"13.3.3 — Approach 3: Subtract — Enforcing the Stem Economy Rule","blocks":[{"type":"step","title":"13.3.3 — Approach 3: Subtract — Enforcing the Stem Economy Rule","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Discard the majority of foreign stems to create acoustic space for original production.  "}]},{"type":"step","title":"1. The Stem Economy Rule (Sam Matla)","blocks":[{"type":"prose","html":"A 20-stem remix pack is an acoustic trap. If you unmute all 20 original stems and try to add your own drums, bass, and synths, the mix turns into an unintelligible wall of mud."},{"type":"list","items":["<strong>The 80/20 Ingestion Law</strong>: Select <strong>1 or 2 essential stems</strong> (Lead Vocal + one signature acoustic riff). Discard or delete the remaining 18 stems. Your original bass, drums, and synthesizers must provide 80% of the acoustic energy."],"ordered":false}]}],"minutes":8},{"id":"production-l13-3-4","title":"13.3.4 — Approach 4: Work Around the Key Element","blocks":[{"type":"step","title":"13.3.4 — Approach 4: Work Around the Key Element","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Anchor all production decisions to the single most memorable element.  "}]},{"type":"step","title":"1. The Anchor Principle","blocks":[{"type":"prose","html":"Identify the \"thing people sing in the shower\"—the vocal topline, the whistling riff, or the iconic synth line. Every new drum fill, bass glide, and chord change you write must actively serve, spotlight, and answer that central anchor element."}]}],"minutes":8},{"id":"production-l13-3-5","title":"13.3.5 — Approach 5: Invert Structure","blocks":[{"type":"step","title":"13.3.5 — Approach 5: Invert Structure","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Subvert original dynamics by placing drops where they broke down.  "}]},{"type":"step","title":"1. Structural Subversion","blocks":[{"type":"list","items":["Where the original track had a quiet, acoustic breakdown  launch your massive, explosive electronic drop.","Where the original track had a loud, driving chorus  strip down to an intimate, filtered ambient interlude with solo piano and vocal.","This creates instant novelty and surprise for listeners who know the original record."],"ordered":false}]}],"minutes":8},{"id":"production-l13-3-6","title":"13.3.6 — Approach 6: Contrast Energy (Dynamic Polarity Shift)","blocks":[{"type":"step","title":"13.3.6 — Approach 6: Contrast Energy (Dynamic Polarity Shift)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Produce a quiet remix of a loud song or a peak-time club remix of an intimate ballad.  "}]},{"type":"step","title":"1. Energy Polarity Transformation","blocks":[{"type":"list","items":["<strong>Aggressive Festival Banger  Intimate Chillout / Lo-Fi</strong>: Strip away the distorted supersaws; re-voice the melody on a warm, decaying Rhodes piano with vinyl warmth at 85 BPM.","<strong>Intimate Acoustic Ballad  Peak-Time Festival Banger</strong>: Accelerate the tempo, build a massive rising snare crescendo, and drop into an explosive 140-BPM melodic bass climax."],"ordered":false}]}],"minutes":8},{"id":"production-l13-3-7","title":"13.3.7 — The 7th Path: \"Keep It Similar\" (The Club Update)","blocks":[{"type":"step","title":"13.3.7 — The 7th Path: \"Keep It Similar\" (The Club Update)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Modernize drums and sub-bass while keeping original chords and melody intact.  "}]},{"type":"step","title":"1. The DJ Utility Update","blocks":[{"type":"prose","html":"In commercial club remixing, producers often keep the original chords, guitars, and vocals completely intact, replacing only the outdated drum kit with a massive, punchy modern kick and sub-bassline to make the track playable on festival sound systems."}]}],"minutes":8},{"id":"production-l13-3-8","title":"13.3.8 — The Second Hook Decision","blocks":[{"type":"step","title":"13.3.8 — The Second Hook Decision","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Introduce an original instrumental drop hook that alternates with the vocal topline.  "}]},{"type":"step","title":"1. Dual-Hook Architecture","blocks":[{"type":"prose","html":"During the remix drop:"},{"type":"list","items":["Bars 1–8: Your original instrumental synth drop lead plays the main driving riff.","Bars 9–16: The vocal acapella returns, singing the original chorus hook on top of the drop groove."],"ordered":false}]}],"minutes":8},{"id":"production-l13-3-9","title":"13.3.9 — Ear Training Listen Cards: Identifying Remix Approaches","blocks":[{"type":"step","title":"13.3.9 — Ear Training Listen Cards: Identifying Remix Approaches","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Analyze and classify official commercial remixes by their underlying approach.  "}]},{"type":"step","title":"1. Analytical Listening Audit","blocks":[{"type":"prose","html":"Audition two official commercial remixes from your library and document:"},{"type":"list","items":["<em>What key element was preserved?</em>","<em>Which of the 6 EDMProd approaches was primarily executed?</em>"],"ordered":true}]}],"minutes":8},{"id":"production-l13-3-10","title":"13.3.10 — Committing to One Approach for Deliverable 3","blocks":[{"type":"step","title":"13.3.10 — Committing to One Approach for Deliverable 3","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Formulate and document the chosen remix architecture in project notes.  "}]},{"type":"step","title":"1. Written Commitment","blocks":[{"type":"prose","html":"Document in <code>REMIX_STRATEGY.txt</code>: Target Approach (e.g., <em>Approach 1 Re-Harmonization + Approach 2 Genre Translation</em>) and Key Element Preserved."}]}],"minutes":8},{"id":"production-l13-4-1","title":"13.4.1 — Authoring NEW Drums and NEW Bass in Live 12 Standard","blocks":[{"type":"step","title":"13.4.1 — Authoring NEW Drums and NEW Bass in Live 12 Standard","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Program original rhythm tracks that provide modern power without masking the vocal.  "}]},{"type":"step","title":"1. The Core Remix Formula","blocks":[{"type":"prose","html":"Remix = SRC\\_Vocal + NEW\\_Drums + NEW\\_Bass + NEW\\_Chords"},{"type":"list","items":["Load Live's stock <strong>Drum Rack</strong> on Track 2 (<code>NEW_DRUMS</code>).","Load Live's stock <strong>Drift</strong> or <strong>Analog</strong> synth on Track 3 (<code>NEW_BASS</code>).","Compose a driving bassline that interlocks with the vocal rhythm, ducking under the kick drum via Live’s stock Compressor sidechain."],"ordered":false}]}],"minutes":8},{"id":"production-l13-4-2","title":"13.4.2 — Session View Remix Layout: vs. Scenes","blocks":[{"type":"step","title":"13.4.2 — Session View Remix Layout: vs. Scenes","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Structure modular remix scenes combining sliced vocal stems with original clips.  "}]},{"type":"step","title":"1. Session Matrix Layout","blocks":[{"type":"list","items":["<strong>Track 1 (<code>SRC_VOX</code>)</strong>: Sliced into 8-bar clips (<code>Verse_Vox</code>, <code>Build_Vox</code>, <code>Chorus_Vox</code>).","<strong>Tracks 2–5 (<code>NEW_</code>)</strong>: Original Drums, Bass, Chords, and FX clips.","<strong>Scene 4 (<code>04_DROP</code>)</strong>: Launches <code>SRC_Chorus_Vox</code> simultaneously with <code>NEW_Drop_Drums</code> and <code>NEW_Drop_Bass</code>."],"ordered":false}]}],"minutes":8},{"id":"production-l13-4-3","title":"13.4.3 — Linear Arrangement Remix Layout","blocks":[{"type":"step","title":"13.4.3 — Linear Arrangement Remix Layout","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Structure continuous stem tracks across the horizontal Arrangement ruler.  "}]},{"type":"step","title":"1. Arrangement Layout","blocks":[{"type":"prose","html":"Place the continuous <code>SRC_Lead_Vocal</code> audio clip across Track 1. Place Locators matching the original vocal sections, and construct your new drums, bass, and synths directly underneath."}]}],"minutes":8},{"id":"production-l13-4-4","title":"13.4.4 — Launchkey MK4 Scene Launching of Remixes","blocks":[{"type":"step","title":"13.4.4 — Launchkey MK4 Scene Launching of Remixes","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Rehearse and trigger remix transitions live using the Launchkey MK4 pads.  "}]},{"type":"step","title":"1. Hardware Performance Operations","blocks":[{"type":"list","items":["Set Launchkey MK4 to <strong>Session / Clip Mode</strong>.","The 2× 8 RGB pads illuminate matching your Session clip colors.","Press Pad Row buttons to launch remix scenes in quantization sync.","Use MK4 Faders 1–8 to balance levels between <code>SRC_VOX</code> and <code>NEW_DRUMS</code> live during the performance pass."],"ordered":false}]}],"minutes":8},{"id":"production-l13-4-5","title":"13.4.5 — Creative Stem Processing: Reversals, Transposition, and Octaves","blocks":[{"type":"step","title":"13.4.5 — Creative Stem Processing: Reversals, Transposition, and Octaves","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Transform foreign stems into expressive transitional sweeps and textures.  "}]},{"type":"step","title":"1. Native Processing Techniques","blocks":[{"type":"list","items":["<strong>The Reverse Vocal Swell</strong>: Slice the first word of the Chorus vocal (<code>Ctrl + E</code>). Press <strong><code>R</code></strong> to reverse it. Insert Live’s stock <code>Reverb</code> at 100% Wet, bounce the tail, reverse it again, and position it leading into Bar 33 Beat 1.1.1 as a custom vocal riser.","<strong>Octave Doubling</strong>: Duplicate the backing vocal stem  Transpose up <strong>+12 st</strong> in Clip View with Complex Pro  Pan 40% Left and 40% Right to create shimmering stereo ear candy."],"ordered":false}]}],"minutes":8},{"id":"production-l13-4-6","title":"13.4.6 — Mangle as Sampling: Vocal Synthesizers (EDMProd #7, #13, #14)","blocks":[{"type":"step","title":"13.4.6 — Mangle as Sampling: Vocal Synthesizers (EDMProd #7, #13, #14)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Synthesize original melodic instruments from short vocal grains.  "}]},{"type":"step","title":"1. Building a Vocal Lead Synth in Live 12 Standard","blocks":[{"type":"list","items":["Slice a 200ms sustained vowel (\"Ah\" or \"Oh\") from the vocal stem.","Drag the slice into a <strong>Simpler</strong> device on a new MIDI track.","In Simpler: Set Mode to <strong>Classic</strong>, Loop to <strong>ON</strong>, Fade to <strong>25 ms</strong>.","Play the Launchkey MK4 keyboard: You now possess a custom melodic vocal synthesizer that perfectly matches the vocal tone of the source singer."],"ordered":true}]}],"minutes":8},{"id":"production-l13-4-7","title":"13.4.7 — Space and Wash as Glue (EDMProd #15)","blocks":[{"type":"step","title":"13.4.7 — Space and Wash as Glue (EDMProd #15)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Bond foreign stems to original production using shared return reverb and delay.  "}]},{"type":"step","title":"1. The Shared Room Acoustic Glue","blocks":[{"type":"prose","html":"Foreign vocal stems recorded in a third-party studio sound disconnected when placed next to dry stock drum samples:"},{"type":"list","items":["Route both <code>SRC_Lead_Vocal</code> and <code>NEW_Chords</code> into <strong>Return Track A (Live Stock Reverb)</strong> and <strong>Return Track B (Live Stock Delay)</strong>.","Sending 15–25% of both tracks into the same virtual acoustic space glues the foreign stem and your new instruments into a cohesive stereo environment."],"ordered":false}]}],"minutes":8},{"id":"production-l13-4-8","title":"13.4.8 — Re-Enforcing the Stem Economy Rule","blocks":[{"type":"step","title":"13.4.8 — Re-Enforcing the Stem Economy Rule","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Conduct mix headroom audits to eliminate dormant foreign stem clutter.  "}]},{"type":"step","title":"1. Headroom Audit","blocks":[{"type":"prose","html":"Confirm that you do not have 14 unused stems running in the background. Delete or mute inactive stem tracks to protect CPU and visual clarity."}]}],"minutes":8},{"id":"production-l13-4-9","title":"13.4.9 — Assembling the 32-Bar Remix Sketch","blocks":[{"type":"step","title":"13.4.9 — Assembling the 32-Bar Remix Sketch","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct, audit, and export a complete 32-bar remix sketch.  "}]},{"type":"step","title":"1. 32-Bar Arrangement Roadmap","blocks":[{"type":"prose","html":"<code>01_Remix_Intro (8b)</code>  <code>02_Build (8b)</code>  <code>03_MAIN_REMIX_DROP (16b)</code>. Export <code>Remix_Sketch_v01.wav</code>."}]}],"minutes":8},{"id":"production-l13-4-10","title":"13.4.10 — The Strangers' Identity Test","blocks":[{"type":"step","title":"13.4.10 — The Strangers' Identity Test","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Verify that the original song remains immediately recognizable.  "}]},{"type":"step","title":"1. The Verification Audit","blocks":[{"type":"prose","html":"Play your 32-bar remix sketch for an independent listener. Confirm that they can immediately identify the original song within 5 seconds of the vocal entry."}]}],"minutes":8}],"exercises":[]},{"id":"production-m-13-2","code":"13","title":"Section C: Remix and Flip Craft (Part B: The Flip)","blurb":"1. A Flip treats source audio not as an identifiable song, but as a granular quarry of raw sound chops. The original song identity is dismantled. 2. Under copyright law, heavy chopping does NOT eliminate derivative liability. Physical sound","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"production-l-o-18","title":"Section overview","blocks":[{"type":"step","title":"overview","blocks":[{"type":"heading","text":"Module 13 — Section C: Remix and Flip Craft (Part B: The Flip)","level":1},{"type":"prose","html":"<strong>Intent:</strong> Master the granular deconstruction and re-sequencing craft of the official music producer Flip. Slice source audio into a 16-pad Drum Rack quarry, perform expressive new rhythmic and melodic patterns across Launchkey MK4 pads (Channel 10, Notes 36–51), understand why copyright persists even when song identity vanishes, and construct a complete 32-bar linear flip arrangement.   <strong>Required Core Module.</strong>   <strong>Strict Pedagogical Invariants:</strong>  "},{"type":"list","items":["A Flip treats source audio not as an identifiable song, but as a granular quarry of raw sound chops. The original song identity is dismantled.","Under copyright law, heavy chopping does NOT eliminate derivative liability. Physical sound recording sampling (℗) requires legal clearance.","Hardware pad mapping is strictly locked to Novation Launchkey MK4 61 (16 pads, Channel 10, Notes 36–51, C1 = Pad 1 bottom-left, Live MPE Checkbox strictly OFF).  "],"ordered":true},{"type":"prose","html":"<strong>Primary Source References:</strong> Ableton Live 12 Reference Manual (Ch. 13: Slicing, Ch. 18: Drum Racks, Ch. 28: Simpler); <em>How to Sample Sounds A Beginners Guide for Music Producers</em>; <em>Drum Breaks_ A Guide To Injecting Character into Your Music.pdf</em>; Novation Launchkey MK4 User Guide &amp; Programmer Reference; EDMProd (#13–14); r/makinghiphop."},{"type":"heading","text":"Section 13.5 — The Flip Path: Granular Deconstruction, Pad Re-Sequencing, and New Identity","level":1},{"type":"prose","html":"<strong>Section ID:</strong> <code>production-m13-5</code>   <strong>Learning Outcomes:</strong>"},{"type":"list","items":["Deconstruct source audio until original song identity is dismantled into raw material.","Slice audio phrases into Live 12 Standard Drum Racks using transient, transient-grid, and region division.","Perform and re-sequence sliced chops across Launchkey MK4 16 Drum Rack pads (Channel 10, Notes 36–51).","Apply granular pad manipulations: choke grouping, per-pad pitching, reversal, and sample start decay.","Compose original harmony and sub-basslines underneath micro-vocal slivers.","Contrast Hip-Hop chops (90 BPM) vs. Club/Future-Bass chops (140 BPM).","Capture a live 16-pad performance pass and assemble a 32-bar linear flip arrangement."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-1","title":"13.5.1 — Flip Remix: The Obliteration of Identity","blocks":[{"type":"step","title":"13.5.1 — Flip Remix: The Obliteration of Identity","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Understand the fundamental artistic divergence between Remix and Flip.  "}]},{"type":"step","title":"1. Artistic Divergence","blocks":[{"type":"list","items":["<strong>The Remix</strong>: Reveres the original song. It preserves the vocal hook so the audience can sing along.","<strong>The Flip</strong>: Treats the original song as raw marble in a quarry. You slice a 2-second vintage piano chord, reverse a 100ms vocal sigh, and re-order fragments into a brand-new groove that has zero melodic resemblance to the original."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-2","title":"13.5.2 — Copyright Does NOT Disappear with Identity","blocks":[{"type":"step","title":"13.5.2 — Copyright Does NOT Disappear with Identity","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Master the legal mechanics of physical sampling and derivative works.  "}]},{"type":"step","title":"1. The Legal Invariant of Physical Sampling","blocks":[{"type":"prose","html":"Beginner producers often believe the myth: <em>\"If I chop a sample so nobody can recognize it, it becomes 100% legal.\"</em>"},{"type":"list","items":["<strong>The Statutory Truth</strong>: Under 17 U.S.C. § 106 and <em>Bridgeport Music</em>, physical sampling of a sound recording (℗) constitutes an unauthorized derivative work regardless of how heavily transformed the audio becomes.","All flip projects in this course must utilize authorized stem packs, royalty-free sample libraries, public domain recordings, or your own original music."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-3","title":"13.5.3 — Slicing to Drum Rack in Live 12 Standard (Ch. 13)","blocks":[{"type":"step","title":"13.5.3 — Slicing to Drum Rack in Live 12 Standard (Ch. 13)","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Slice 2-bar and 4-bar phrases into a 16-pad Drum Rack matrix.  "}]},{"type":"step","title":"1. Slicing Workflow","blocks":[{"type":"list","items":["Ingest an audio phrase onto an audio track (e.g., a 2-bar vintage soul piano sample).","Right-click the audio clip  Select <strong>Slice to New MIDI Track</strong>.","In the Slicing Dialogue:","<strong>Create one slice per</strong>: Select <strong>Transient</strong> (for organic acoustic hits) or <strong>1/8th Note / 1/16th Note</strong> (for rhythmic loops).","<strong>Slicing Preset</strong>: Select <strong>Built-in Slicing Preset</strong> (which loads a standard Drum Rack containing 16 Simpler instances).","Live generates a new MIDI track with pads 1–16 populated by the slices."],"ordered":true},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">graph TD\n    Source[\"2-Bar Audio Phrase (Audio Track)\"]\n    Source --&gt;|Right-Click -&gt; Slice to New MIDI Track| SlicingEngine[\"Live 12 Slicing Engine\"]\n    SlicingEngine --&gt; DR[\"Drum Rack (16 Simpler Instances)\"]\n    DR --&gt; P1[\"Pad 1 (C1 / Note 36): Slice 1\"]\n    DR --&gt; P2[\"Pad 2 (C#1 / Note 37): Slice 2\"]\n    DR --&gt; P16[\"Pad 16 (D#2 / Note 51): Slice 16\"]</pre>"}]}],"minutes":8},{"id":"production-l13-5-4","title":"13.5.4 — Launchkey MK4 Re-Sequencing: Channel 10, Notes 36–51","blocks":[{"type":"step","title":"13.5.4 — Launchkey MK4 Re-Sequencing: Channel 10, Notes 36–51","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Map Drum Rack pads to Launchkey MK4 hardware pads for live tactile triggering.  "}]},{"type":"step","title":"1. Hardware Pad Protocol","blocks":[{"type":"prose","html":"Set the Novation Launchkey MK4 61 to <strong>Drum Mode</strong>:"},{"type":"list","items":["Pad 1 (Bottom-Left) = MIDI Note 36 (C1)  Triggers Drum Rack Pad 1.","Pad 8 (Bottom-Right) = MIDI Note 43 (G1)  Triggers Drum Rack Pad 8.","Pad 9 (Top-Left) = MIDI Note 44 (G\\#1)  Triggers Drum Rack Pad 9.","Pad 16 (Top-Right) = MIDI Note 51 (D\\#2)  Triggers Drum Rack Pad 16.","<strong>Performance Exercise</strong>: Tap the pads completely out of their chronological order (e.g., 7 3 12 2) to discover a brand-new syncopated rhythm."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-5","title":"13.5.5 — Granular Pad Manipulations: Choke Groups, Pitch, and Reverse","blocks":[{"type":"step","title":"13.5.5 — Granular Pad Manipulations: Choke Groups, Pitch, and Reverse","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Sculpt individual Drum Rack pad parameters to create tight, responsive playback.  "}]},{"type":"step","title":"1. The Three Essential Pad Controls","blocks":[{"type":"list","items":["<strong>Choke Group 1</strong>: In the Drum Rack Chain List, set all 16 pads to <strong>Choke Group 1</strong>. When you tap Pad 2, it instantly cuts off the audio of Pad 1, preventing muddy sample overlapping.","<strong>Per-Pad Transposition</strong>: Click Pad 3  In Simpler, adjust <code>Transpose</code> to <strong>+7 st</strong> (up a fifth).","<strong>Per-Pad Reversal</strong>: Click Pad 7  Click the <strong>Rev</strong> button in Simpler to play that slice backwards."],"ordered":true}]}],"minutes":8},{"id":"production-l13-5-6","title":"13.5.6 — Unwarped Tap-to-Grid Alternative Workflow","blocks":[{"type":"step","title":"13.5.6 — Unwarped Tap-to-Grid Alternative Workflow","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Capture organic vinyl feel by chopping unwarped audio directly on the timeline.  "}]},{"type":"step","title":"1. The Organic Hip-Hop Chop","blocks":[{"type":"prose","html":"Instead of forcing a loose, human vinyl sample to conform to Live's digital warp grid:"},{"type":"list","items":["Turn <strong>Warp OFF</strong> on the audio clip.","Tap tempo in Live (<code>Tap</code> button) to match the song's natural tempo.","Slice the unwarped audio manually using <strong><code>Ctrl + E</code></strong> and position the sliced clips directly along the timeline."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-7","title":"13.5.7 — Writing Original Harmony Under a Micro-Vocal Sliver","blocks":[{"type":"step","title":"13.5.7 — Writing Original Harmony Under a Micro-Vocal Sliver","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Compose brand-new chord progressions under a 200ms vocal chop.  "}]},{"type":"step","title":"1. Harmonic Anchoring","blocks":[{"type":"prose","html":"Take a tiny 200ms vocal vowel slice on Pad 1:"},{"type":"list","items":["Load <strong>Drift</strong> or <strong>Electric</strong> on Track 3.","Compose a 4-bar chord progression in F Minor (Fm - Db - Ab - Eb).","Trigger the vocal chop on the 16th-note upbeats as a syncopated hook instrument."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-8","title":"13.5.8 — Hip-Hop Flip vs. Club Flip: Same Tools, Divergent Forms","blocks":[{"type":"step","title":"13.5.8 — Hip-Hop Flip vs. Club Flip: Same Tools, Divergent Forms","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Apply identical slicing tools across boom-bap vs. club/future bass architectures.  "}]},{"type":"step","title":"1. Stylistic Form Divergence","blocks":[{"type":"list","items":["<strong>Boom-Bap Hip-Hop Flip (88–92 BPM)</strong>: Sliced jazz chords, swing quantization (16 Swing 58%), uncompressed acoustic snare on Beat 2 and 4.","<strong>Club / Future Bass Flip (140–150 BPM)</strong>: High-speed vocal chops, sidechained to 4-on-the-floor kick, detuned supersaw layers, and 808 sub-bass drops."],"ordered":false}]}],"minutes":8},{"id":"production-l13-5-9","title":"13.5.9 — Typologies: Phrase vs. One-Shot vs. Granular Grain","blocks":[{"type":"step","title":"13.5.9 — Typologies: Phrase vs. One-Shot vs. Granular Grain","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Categorize sample assets by temporal length and functional role.  "}]},{"type":"step","title":"1. Sample Typology Matrix","blocks":[{"type":"table","headers":["Typology","Time Length","Musical Function in Flip"],"rows":[["<strong>Phrase</strong>","1 to 2 Bars (1.0–3.0 sec)","Rhythmic foundation or groove anchor."],["<strong>One-Shot</strong>","1 Beat (200–500 ms)","Isolated snare, piano chord, or vocal word."],["<strong>Grain</strong>","Micro-sliver (10–50 ms)","Looped inside Simpler to synthesize a custom waveform."]],"caption":null}]}],"minutes":8},{"id":"production-l13-5-10","title":"13.5.10 — Recording the 16-Pad Hardware Performance Pass","blocks":[{"type":"step","title":"13.5.10 — Recording the 16-Pad Hardware Performance Pass","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Capture live expressive finger-drumming passes in real time.  "}]},{"type":"step","title":"1. Performance Recording Protocol","blocks":[{"type":"list","items":["Arm the Drum Rack MIDI track.","Engage metronome pre-roll.","Press <strong>Arrangement Record (<code>●</code>)</strong>.","Perform your 16-pad re-sequenced pattern live from the Launchkey MK4 pads for 32 continuous bars.","Apply non-destructive 1/16th quantization if necessary (<code>Ctrl + U</code>)."],"ordered":true}]}],"minutes":8},{"id":"production-l13-5-11","title":"13.5.11 — Assembling the 32-Bar Linear Flip Arrangement","blocks":[{"type":"step","title":"13.5.11 — Assembling the 32-Bar Linear Flip Arrangement","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Construct, audit, and export a complete 32-bar linear flip sketch.  "}]},{"type":"step","title":"1. 32-Bar Flip Timeline","blocks":[{"type":"prose","html":"<code>01_Flip_Intro (8b)</code>  <code>02_Chop_Verse (8b)</code>  <code>03_Build (8b)</code>  <code>04_MAIN_FLIP_DROP (8b)</code>. Export <code>Flip_Sketch_v01.wav</code>."}]}],"minutes":8},{"id":"production-l13-5-12","title":"13.5.12 — The Formal Deconstruction Audit","blocks":[{"type":"step","title":"13.5.12 — The Formal Deconstruction Audit","blocks":[{"type":"prose","html":"<strong>Short description:</strong> Document the transformation of source audio in project notes.  "}]},{"type":"step","title":"1. Audit Documentation","blocks":[{"type":"prose","html":"Document in <code>FLIP_AUDIT.txt</code>:"},{"type":"list","items":["Source material sampled.","Number of Drum Rack slices generated.","Explanation of how original identity was dismantled into a new original piece."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
